<span class="line"><span style="color:#ABB2BF;">    zskiplistNode </span><span style="color:#C678DD;">*</span><span style="color:#E06C75;">update</span><span style="color:#ABB2BF;">[ZSKIPLIST_MAXLEVEL];</span><span style="color:#7F848E;font-style:italic;">  // 每层的前驱节点</span></span>
