<span class="line"><span style="color:#ABB2BF;">               (</span><span style="color:#E5C07B;">x</span><span style="color:#ABB2BF;">-&gt;</span><span style="color:#E06C75;">level</span><span style="color:#ABB2BF;">[i].</span><span style="color:#E5C07B;">forward</span><span style="color:#ABB2BF;">-&gt;</span><span style="color:#E06C75;">score</span><span style="color:#C678DD;"> &lt;</span><span style="color:#ABB2BF;"> score </span><span style="color:#56B6C2;">||</span></span>
